import math

def tau(n):
    """Calculates the number of positive divisors of n."""
    if n <= 0:
        return 0 # Should not happen for n >= 1
    if n == 1:
        return 1

    count = 1
    d = 2
    temp = n

    while d * d <= temp:
        exponent = 0
        while temp % d == 0:
            exponent += 1
            temp //= d
        if exponent > 0:
            count *= (exponent + 1)
        d += 1

    if temp > 1:
        # The remaining temp is a prime factor
        count *= 2

    return count

def d(n):
    """Calculates the number of positive divisors of n other than 1 and itself."""
    if n == 1:
        return 0
    return tau(n) - 2

# Brute force search for n from 1 to 1000
