import math

def count_divisors(k):
    if k <= 0:
        return 0
    if k == 1:
        return 1
    count = 0
    # Iterate up to sqrt(k)
    for i in range(1, int(math.sqrt(k)) + 1):
        if k % i == 0:
            # If divisors are equal (i*i = k), count only once
            if i * i == k:
                count += 1
            # Otherwise, count both i and k/i
            else:
                count += 2
    return count

def solve_case_a2(limit=10000):
    print(f"Searching for n such that tau(n) = 4 and tau(n+735) = 4 for n < {limit}...")
    for n in range(1, limit):
        # Check tau(n) = 4
        if count_divisors(n) == 4:
            n_plus_735 = n + 735
            # Check tau(n+735) = 4
            if count_divisors(n_plus_735) == 4:
                print(f"Found solution n = {n}. n + 735 = {n_plus_735}")
                return n
    print("No solution found within the given limit.")
    return None

# Since 735 is relatively small, let's start with a reasonable limit.
# 10000 should be sufficient for initial investigation.
solution_n = solve_case_a2(limit=10000)

if solution_n is not None:
    # Check the required forms explicitly for verification/understanding
    n = solution_n
    if count_divisors(n) != 4 or count_divisors(n + 735) != 4:
        print("Error in finding the solution.")
else:
