def is_prime(k):
    if k <= 1:
        return False
    if k <= 3:
        return True
    if k % 2 == 0 or k % 3 == 0:
        return False
    i = 5
    while i * i <= k:
        if k % i == 0 or k % (i + 2) == 0:
            return False
        i += 6
    return True

limit = 5000 # Increased limit slightly just in case
found_pair = None

# We only need to check odd primes n > 2, since if n=2, n+735 = 737.
# 737 = 11 * 67. Not prime.
for n in range(3, limit, 2):
    if is_prime(n):
        n_plus_735 = n + 735
        if is_prime(n_plus_735):
            found_pair = (n, n_plus_735)
            break

if found_pair:
    print(f"Found pair: {found_pair}")
else:
    print("No pair found up to the limit.")

